@font-face {
    font-family: 'Indy Sans Regular';
    src: url('https://assets.the-independent.com/fonts/Independent-Sans-Regular.woff2') format('woff2');
}

@font-face {
    font-family: 'Indy Sans Medium';
    src: url('https://assets.the-independent.com/fonts/Independent-Sans-Medium.woff2') format('woff2');
}

@font-face {
    font-family: 'Indy Serif Bold';
    src: url('https://assets.the-independent.com/fonts/Independent-Serif-Bold.woff2') format('woff2');
}

.accordion, button {
    font-family: 'Indy Sans Medium', sans-serif !important;
}

p.global-font, .global-font p {
    font-family: 'Indy Sans Regular', sans-serif !important;
}

h1 {
    font-family: 'Indy Serif Bold', serif !important;
}

.message {
    background-position: right;
    background-color: #ffffff;
}

@media only screen and (max-width: 1000px) {
    .message-component.main-container {
        width: 94% !important;
    }
}

@media only screen and (max-width: 600px) {
    .cta-container{
        display: flex;
        flex-direction: column;
    }

    .accept-all, .reject-all,.show-purposes{
        margin: 0 0 15px 0 !important;
        width: 100% !important;
    }

    .accept-all{
        order: 1;
    }

    .reject-all{
        order: 2;
    }

    .show-purposes{
        order: 3;
    }
}

.message-component.main-container {
    margin: 0 auto !important;
    overflow-y: scroll;
}

.message-stacksclose {
    display: none;
}

.message-stacks .panel p {
    font-family: 'Indy Sans Regular', sans-serif !important;
}

.message-stacks .stack:hover {
    background-color: #fff !important;
}

.chevron.down:before, .chevron.up:before {
    font-size: 14px;
}

button:focus {
    box-shadow: none;
}
